+			return loginURLContinue, errors.Join(result.err, finishErr)
+		}
+		if finishErr != nil {
+			return loginURLContinue, fmt.Errorf("restore terminal input: %w", finishErr)
+		}
+		return result.action, nil
+	}
+}
